3	
4	import type { DashState, LiveEvent, NodeState, TimelineLine, WsMessage } from "./types";
5	
6	export const initialState: DashState = {
7	  nodes: {},
8	  counters: { active_nodes: 0, threats_detected: 0, filters_deployed: 0, frames_blocked: 0 },
9	  timeline: [],
10	  stage: "idle",
11	  activeNode: null,
12	  activeAttack: null,
13	  agent: { iterations: null, self_tpr: null, self_fpr: null },
14	  agentStatus: null,
15	  error: null,
16	  seq: 0,
17	};
18	
19	const PROGRESS_PREFIX = "⏳";
20	
21	const STAGE_BY_TYPE: Partial<Record<LiveEvent["type"], DashState["stage"]>> = {
22	  ANOMALY_DETECTED: "trigger",
23	  AGENT_ANALYZING: "agent",
24	  VERIFYING: "verify",
25	  OTA_DEPLOYING: "ota",
26	  DEPLOYED: "done",
27	};
