29	function describe(e: LiveEvent): { text: string; tone: TimelineLine["tone"] } {
30	  const p = e.payload;
31	  const node = e.node_id ?? "system";
32	  switch (e.type) {
33	    case "NODE_UP":
34	      return { text: `${node} online`, tone: "info" };
35	    case "NODE_DOWN":
36	      return { text: `${node} went offline`, tone: "bad" };
37	    case "ANOMALY_DETECTED":
38	      return { text: `${node} anomaly: ${p.count ?? "?"} frames in window`, tone: "warn" };
39	    case "AGENT_ANALYZING":
40	      return { text: `${node} agent analyzing (attempt ${p.attempt ?? 1})`, tone: "info" };
41	    case "AGENT_STEP":
42	      return { text: `${node} sandbox: ${p.text ?? ""}`, tone: "info" };
43	    case "FILTER_GENERATED": {
44	      const iters = p.iterations ? ` (${p.iterations} sandbox iters)` : "";
45	      return { text: `${node} filter generated: ${p.attack_class ?? "?"}${iters}`, tone: "info" };
46	    }
47	    case "VERIFYING":
48	      return { text: `${node} verifying filter (replay test)`, tone: "info" };
49	    case "VERIFY_FAILED":
50	      return { text: `${node} verify FAILED ${p.tests ?? ""} (fpr=${p.fpr ?? "?"})`, tone: "bad" };
51	    case "VERIFY_PASSED":
52	      return { text: `${node} verify PASSED ${p.tests ?? ""}`, tone: "ok" };
53	    case "OTA_DEPLOYING":
54	      return { text: `${node} deploying filter OTA`, tone: "info" };
55	    case "DEPLOYED":
56	      return { text: `${node} PROTECTED: ${p.attack_class ?? "filter"} deployed`, tone: "ok" };
57	    case "FRAME_BLOCKED":
58	      return { text: `${node} blocked ${p.count ?? 1} attack frames`, tone: "ok" };
59	    default:
60	      return { text: e.type, tone: "info" };
61	  }
62	}
63	
64	function setNodeState(state: DashState, nodeId: string | null, ns: NodeState): DashState["nodes"] {
65	  if (!nodeId || !state.nodes[nodeId]) return state.nodes;
66	  return { ...state.nodes, [nodeId]: { ...state.nodes[nodeId], state: ns } };
67	}
68	
69	export function reduce(state: DashState, msg: WsMessage): DashState {
70	  if (msg.type === "SNAPSHOT") {
71	    const nodes: DashState["nodes"] = {};
72	    for (const n of msg.payload.nodes) nodes[n.node_id] = n;
73	    return { ...state, nodes, counters: msg.payload.counters };
74	  }
75	
76	  const e = msg;
77	  let nodes = state.nodes;
78	  const counters = { ...state.counters };
79	  let activeNode = state.activeNode;
80	  let activeAttack = state.activeAttack;
81	  let agent = state.agent;
82	  let agentStatus = state.agentStatus;
83	  let error = state.error;
84	  let appendLine = true;
85	
86	  switch (e.type) {
87	    case "NODE_UP":
88	      if (e.node_id && !nodes[e.node_id]) {
89	        nodes = {
90	          ...nodes,
91	          [e.node_id]: {
92	            node_id: e.node_id,
93	            state: "NORMAL",
94	            last_seen: e.ts,
95	            fw_version: "v1",
96	            label: e.node_id,
97	            blocked: 0,
98	          },
99	        };
100	      }
101	      break;
102	    case "NODE_DOWN":
103	      nodes = setNodeState(state, e.node_id, "OFFLINE");
104	      break;
105	    case "ANOMALY_DETECTED":
106	      nodes = setNodeState(state, e.node_id, "ALERT");
107	      counters.threats_detected += 1;
108	      activeNode = e.node_id;
109	      agent = { iterations: null, self_tpr: null, self_fpr: null };
110	      agentStatus = null;
111	      error = null;
112	      break;
113	    case "AGENT_STEP": {
114	      const text = String(e.payload.text ?? "");
115	      if (text.startsWith(PROGRESS_PREFIX)) {
116	        agentStatus = text; // live status — do not spam the timeline
117	        appendLine = false;
118	      } else if (text.toLowerCase().includes("unavailable")) {
119	        error = text; // agent unreachable — surface loudly
120	      }
121	      break;
122	    }
123	    case "FILTER_GENERATED":
124	      activeAttack = (e.payload.attack_class as string) ?? activeAttack;
125	      agent = {
126	        iterations: (e.payload.iterations as number) ?? null,
127	        self_tpr: (e.payload.self_tpr as number) ?? null,
128	        self_fpr: (e.payload.self_fpr as number) ?? null,
129	      };
130	      break;
131	    case "OTA_DEPLOYING":
132	      nodes = setNodeState(state, e.node_id, "UPDATING");
133	      break;
134	    case "DEPLOYED":
135	      nodes = setNodeState(state, e.node_id, "PROTECTED");
136	      counters.filters_deployed += 1;
137	      agentStatus = null; // done working
138	      break;
139	    case "FRAME_BLOCKED": {
140	      const c = Number(e.payload.count ?? 1);
141	      counters.frames_blocked += c;
142	      if (e.node_id && nodes[e.node_id]) {
143	        nodes = {
144	          ...nodes,
145	          [e.node_id]: { ...nodes[e.node_id], blocked: nodes[e.node_id].blocked + c },
146	        };
147	      }
148	      break;
149	    }
150	    default:
151	      break;
152	  }
153	
154	  counters.active_nodes = Object.values(nodes).filter((n) => n.state !== "OFFLINE").length;
155	
156	  const stage = STAGE_BY_TYPE[e.type] ?? state.stage;
157	  let timeline = state.timeline;
