95	  let agent = state.agent;
96	  let agentStatus = state.agentStatus;
97	  let error = state.error;
98	  let appendLine = true;
99	
100	  switch (e.type) {
101	    case "NODE_UP":
102	      if (e.node_id && !nodes[e.node_id]) {
103	        nodes = {
104	          ...nodes,
105	          [e.node_id]: {
106	            node_id: e.node_id,
107	            state: "NORMAL",
108	            last_seen: e.ts,
109	            fw_version: "v1",
110	            label: e.node_id,
111	            blocked: 0,
112	          },
113	        };
114	      }
115	      break;
116	    case "NODE_DOWN":
117	      nodes = setNodeState(state, e.node_id, "OFFLINE");
118	      break;
119	    case "ANOMALY_DETECTED":
120	      nodes = setNodeState(state, e.node_id, "ALERT");
121	      counters.threats_detected += 1;
122	      activeNode = e.node_id;
123	      agent = { iterations: null, self_tpr: null, self_fpr: null };
124	      agentStatus = null;
125	      error = null;
126	      break;
127	    case "AGENT_STEP": {
128	      const text = String(e.payload.text ?? "");
129	      if (text.startsWith(PROGRESS_PREFIX)) {
130	        agentStatus = text; // live status — do not spam the timeline
131	        appendLine = false;
132	      } else if (text.toLowerCase().includes("unavailable")) {
133	        error = text; // agent unreachable — surface loudly
134	      }
135	      break;
136	    }
137	    case "FILTER_GENERATED":
138	      activeAttack = (e.payload.attack_class as string) ?? activeAttack;
139	      agent = {
140	        iterations: (e.payload.iterations as number) ?? null,
141	        self_tpr: (e.payload.self_tpr as number) ?? null,
142	        self_fpr: (e.payload.self_fpr as number) ?? null,
143	      };
144	      break;
