178	    timeline = [line, ...state.timeline].slice(0, 60);
179	  }
180	
181	  return {
182	    ...state,
183	    nodes,
184	    counters,
185	    timeline,
186	    stage,
187	    activeNode,
188	    activeAttack,
189	    agent,
190	    agentStatus,
191	    error,
192	    seq: state.seq + 1,
193	  };
194	}
