it("collects incidents from all domains into one newest-first feed", () => {
  let s = reduce(initialState, snapshot);
  s = reduce(s, ev("INCIDENT_CREATED", null, { id: 1, source: "LINK", severity: "CRITICAL", title: "bad link", verdict: "malicious" }));
  s = reduce(s, ev("INCIDENT_CREATED", null, { id: 2, source: "EMAIL", severity: "WARNING", title: "flagged email" }));
  expect(s.incidents.length).toBe(2);
  expect(s.incidents[0].source).toBe("EMAIL"); // newest first
  expect(s.incidents[1].source).toBe("LINK");
  expect(s.counters.threats_detected).toBe(2);
});

it("stamps the server incident id onto timeline lines", () => {
  let s = reduce(initialState, snapshot);
  s = reduce(s, ev("ANOMALY_DETECTED", "esp-01", { count: 5, incident_id: "inc-0001" }));
  expect(s.timeline[0].incidentId).toBe("inc-0001");
  // absent incident_id falls back to null, never undefined
  s = reduce(s, ev("NODE_UP", "esp-02"));
  expect(s.timeline[0].incidentId).toBeNull();
});

